package com.mei.zhgy.service.knowledge;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import javax.sql.DataSource;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

/**
 * Minimum persisted Knowledge Backend V1.  Versions are append-only and a
 * document has one explicit current_version_id.  The service deliberately
 * exposes command-shaped methods instead of a generic CRUD surface.
 */
@Service
public class KnowledgeBackendService {
    public static final String PACKAGED = "PACKAGED";
    public static final String USER_MANAGED = "USER_MANAGED";
    public static final String EXTERNAL_REFERENCE = "EXTERNAL_REFERENCE";
    private static final String ACTIVE = "ACTIVE";
    private static final String DISABLED = "DISABLED";
    private final DataSource dataSource;
    private final ObjectMapper mapper;
    private final boolean allowFallback;
    private volatile boolean schemaChecked;
    private final Map<String, Map<String,Object>> fallbackSources = new ConcurrentHashMap<>();
    private final Map<String, Map<String,Object>> fallbackDocuments = new ConcurrentHashMap<>();
    private final Map<String, Map<String,Object>> fallbackVersions = new ConcurrentHashMap<>();
    private final Map<String, Map<String,Object>> fallbackEvents = new ConcurrentHashMap<>();

    public KnowledgeBackendService() { this(null, new ObjectMapper().findAndRegisterModules(), true); }
    @Autowired
    public KnowledgeBackendService(@Autowired(required = false) DataSource dataSource, ObjectMapper mapper) {
        this(dataSource, mapper, false);
    }
    public KnowledgeBackendService(DataSource dataSource, ObjectMapper mapper, boolean allowFallback) {
        this.dataSource = dataSource; this.mapper = mapper == null ? new ObjectMapper().findAndRegisterModules() : mapper.findAndRegisterModules(); this.allowFallback = allowFallback;
    }

    public boolean hasPersistentStore() { return dataSource != null; }

    public Map<String,Object> createSource(Map<String,Object> input, Long actorId) {
        requireActor(actorId); String name = required(input, "name"); String type = upper(input, "sourceType", USER_MANAGED);
        if (!USER_MANAGED.equals(type) && !EXTERNAL_REFERENCE.equals(type)) throw KnowledgeBackendException.validation("sourceType 只能是 USER_MANAGED 或 EXTERNAL_REFERENCE");
        Map<String,Object> source = new LinkedHashMap<>(); source.put("sourceId", id("knowledge-source")); source.put("name", name); source.put("sourceType", type); source.put("description", optional(input,"description")); source.put("originUri", optional(input,"originUri")); source.put("ownerUserId", actorId); source.put("status", ACTIVE); now(source);
        if (dataSource == null) { requireFallback(); fallbackSources.put((String)source.get("sourceId"), source); fallbackEvent(source, "KNOWLEDGE_SOURCE_CREATED", actorId); return copy(source); }
        try (Connection c=dataSource.getConnection()) { ensureSchema(c); insertSource(c, source, actorId); return source; } catch (KnowledgeBackendException e){throw e;} catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Source 未持久化",e);}
    }

    public List<Map<String,Object>> listSources(Long actorId) {
        requireActor(actorId); if(dataSource==null){requireFallback(); return fallbackSources.values().stream().filter(s->visible(s,actorId)).map(this::copy).sorted(Comparator.comparing(s->String.valueOf(s.get("createdAt")))).toList();}
        try(Connection c=dataSource.getConnection()){ensureSchema(c); List<Map<String,Object>> out=new ArrayList<>(); try(PreparedStatement p=c.prepareStatement("SELECT source_id,name,source_type,description,origin_uri,owner_user_id,status,created_at,updated_at FROM knowledge_sources WHERE owner_user_id IS NULL OR owner_user_id=? ORDER BY created_at")){p.setLong(1,actorId); try(ResultSet r=p.executeQuery()){while(r.next())out.add(sourceRow(r));}} return out;}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Source 查询不可用",e);}
    }
    public Map<String,Object> getSource(String sourceId, Long actorId) { requireActor(actorId); Map<String,Object>s=source(sourceId); authorize(s,actorId); return copy(s); }
    public List<Map<String,Object>> listDocuments(String sourceId, Long actorId){ Map<String,Object>s=getSource(sourceId,actorId); if(dataSource==null)return fallbackDocuments.values().stream().filter(d->sourceId.equals(d.get("sourceId"))).map(this::copy).toList(); try(Connection c=dataSource.getConnection()){ensureSchema(c);List<Map<String,Object>>o=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT document_id,source_id,title,external_reference,owner_user_id,status,current_version_id,version,created_at,updated_at FROM knowledge_documents WHERE source_id=? ORDER BY created_at")){p.setString(1,sourceId);try(ResultSet r=p.executeQuery()){while(r.next())o.add(documentRow(r));}}return o;}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Document 查询不可用",e);} }
    public Map<String,Object> createDocument(String sourceId, Map<String,Object> input, Long actorId){Map<String,Object>s=getSource(sourceId,actorId); if(PACKAGED.equals(s.get("sourceType")))throw KnowledgeBackendException.forbidden(sourceId);String title=required(input,"title");Map<String,Object>d=new LinkedHashMap<>();d.put("documentId",id("knowledge-document"));d.put("sourceId",sourceId);d.put("title",title);d.put("externalReference",optional(input,"externalReference"));d.put("ownerUserId",actorId);d.put("status",ACTIVE);d.put("currentVersionId",null);d.put("version",0L);now(d);if(dataSource==null){requireFallback();fallbackDocuments.put((String)d.get("documentId"),d);fallbackEvent(d,"KNOWLEDGE_DOCUMENT_CREATED",actorId);return copy(d);}try(Connection c=dataSource.getConnection()){ensureSchema(c);try(PreparedStatement p=c.prepareStatement("INSERT INTO knowledge_documents(document_id,source_id,title,external_reference,owner_user_id,status,current_version_id,version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)")){p.setString(1,(String)d.get("documentId"));p.setString(2,sourceId);p.setString(3,title);set(p,4,d.get("externalReference"));p.setLong(5,actorId);p.setString(6,ACTIVE);p.setNull(7,Types.VARCHAR);p.setLong(8,0);p.setTimestamp(9,ts(d.get("createdAt")));p.setTimestamp(10,ts(d.get("updatedAt")));p.executeUpdate();}insertEvent(c,String.valueOf(d.get("documentId")),"DOCUMENT_CREATED",actorId,null,d);return d;}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Document 未持久化",e);}}
    public Map<String,Object> getDocument(String documentId,Long actorId){requireActor(actorId);Map<String,Object>d=document(documentId);Map<String,Object>s=source(String.valueOf(d.get("sourceId")));authorize(s,actorId);return copy(d);}
    public List<Map<String,Object>> listVersions(String documentId,Long actorId){Map<String,Object>d=getDocument(documentId,actorId);if(dataSource==null)return fallbackVersions.values().stream().filter(v->documentId.equals(v.get("documentId"))).sorted(Comparator.comparing(v->((Number)v.get("versionNumber")).intValue())).map(this::copy).toList();try(Connection c=dataSource.getConnection()){ensureSchema(c);List<Map<String,Object>>o=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT version_id,document_id,version_number,content_type,content,content_hash,created_by,created_at FROM knowledge_versions WHERE document_id=? ORDER BY version_number")){p.setString(1,documentId);try(ResultSet r=p.executeQuery()){while(r.next())o.add(versionRow(r));}}return o;}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Version 查询不可用",e);}}
    public Map<String,Object> getVersion(String versionId,Long actorId){requireActor(actorId);Map<String,Object>v=version(versionId);Map<String,Object>d=document(String.valueOf(v.get("documentId")));authorize(source(String.valueOf(d.get("sourceId"))),actorId);return copy(v);}
    public Map<String,Object> createVersion(String documentId,Map<String,Object> input,Long actorId){Map<String,Object>d=getDocument(documentId,actorId);Map<String,Object>s=source(String.valueOf(d.get("sourceId")));if(PACKAGED.equals(s.get("sourceType")))throw KnowledgeBackendException.forbidden(documentId);String content=normalize(required(input,"content"));String hash=sha256(content);if(dataSource==null){requireFallback();for(Map<String,Object>v:fallbackVersions.values())if(documentId.equals(v.get("documentId"))&&hash.equals(v.get("contentHash")))return copy(v);int n=fallbackVersions.values().stream().filter(v->documentId.equals(v.get("documentId"))).mapToInt(v->((Number)v.get("versionNumber")).intValue()).max().orElse(0)+1;Map<String,Object>v=new LinkedHashMap<>();v.put("versionId",id("knowledge-version"));v.put("documentId",documentId);v.put("versionNumber",n);v.put("contentType",optional(input,"contentType")==null?"text/plain":optional(input,"contentType"));v.put("content",content);v.put("contentHash",hash);v.put("createdBy",actorId);now(v);fallbackVersions.put((String)v.get("versionId"),v);fallbackEvent(v,"KNOWLEDGE_VERSION_CREATED",actorId);return copy(v);}try(Connection c=dataSource.getConnection()){ensureSchema(c);c.setAutoCommit(false);try{Map<String,Object>existing=findVersionByHash(c,documentId,hash);if(existing!=null){c.commit();return existing;}int n=nextVersion(c,documentId);Map<String,Object>v=new LinkedHashMap<>();v.put("versionId",id("knowledge-version"));v.put("documentId",documentId);v.put("versionNumber",n);v.put("contentType",optional(input,"contentType")==null?"text/plain":optional(input,"contentType"));v.put("content",content);v.put("contentHash",hash);v.put("createdBy",actorId);now(v);insertVersion(c,v);insertEvent(c,(String)v.get("versionId"),"VERSION_CREATED",actorId,null,v);c.commit();return v;}catch(Exception e){try{c.rollback();}catch(Exception ignored){}if(e instanceof SQLException && isDuplicate((SQLException)e)){Map<String,Object>existing=findVersionByHash(c,documentId,hash);if(existing!=null)return existing;}if(e instanceof KnowledgeBackendException k)throw k;throw e;}finally{try{c.setAutoCommit(true);}catch(Exception ignored){}}}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Version 未持久化",e);}}
    public Map<String,Object> activateVersion(String documentId,String versionId,Long actorId){Map<String,Object>d=getDocument(documentId,actorId);Map<String,Object>s=source(String.valueOf(d.get("sourceId")));if(!ACTIVE.equals(s.get("status"))||!ACTIVE.equals(d.get("status")))throw KnowledgeBackendException.conflict("KNOWLEDGE_DISABLED","Source 或 Document 已禁用",documentId);if(PACKAGED.equals(s.get("sourceType"))&&actorId!=null)throw KnowledgeBackendException.forbidden(documentId);Map<String,Object>v=getVersion(versionId,actorId);if(!documentId.equals(v.get("documentId")))throw KnowledgeBackendException.conflict("KNOWLEDGE_PROVENANCE_CONFLICT","Version 不属于指定 Document",versionId);if(dataSource==null){requireFallback();d.put("currentVersionId",versionId);d.put("version",((Number)d.get("version")).longValue()+1);d.put("updatedAt",Instant.now().toString());fallbackDocuments.put(documentId,d);fallbackEvent(d,"KNOWLEDGE_VERSION_ACTIVATED",actorId);return copy(d);}try(Connection c=dataSource.getConnection()){ensureSchema(c);c.setAutoCommit(false);try(PreparedStatement lock=c.prepareStatement("SELECT current_version_id,version FROM knowledge_documents WHERE document_id=? FOR UPDATE")){lock.setString(1,documentId);try(ResultSet r=lock.executeQuery()){if(!r.next())throw KnowledgeBackendException.notFound("DOCUMENT_NOT_FOUND","Knowledge Document 不存在",documentId);try(PreparedStatement p=c.prepareStatement("UPDATE knowledge_documents SET current_version_id=?,version=version+1,updated_at=? WHERE document_id=?")){p.setString(1,versionId);p.setTimestamp(2,Timestamp.from(Instant.now()));p.setString(3,documentId);p.executeUpdate();}}}insertEvent(c,documentId,"VERSION_ACTIVATED",actorId,d,v);c.commit();Map<String,Object>updated=getDocument(documentId,actorId);return updated;}catch(KnowledgeBackendException e){throw e;}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Version 激活未提交",e);}}
    public Map<String,Object> setSourceStatus(String sourceId,String status,Long actorId){Map<String,Object>s=getSource(sourceId,actorId);if(PACKAGED.equals(s.get("sourceType")))throw KnowledgeBackendException.forbidden(sourceId);if(!ACTIVE.equals(status)&&!DISABLED.equals(status))throw KnowledgeBackendException.validation("status 只能是 ACTIVE 或 DISABLED");if(dataSource==null){s.put("status",status);s.put("updatedAt",Instant.now().toString());fallbackSources.put(sourceId,s);fallbackEvent(s,"KNOWLEDGE_SOURCE_"+status,actorId);return copy(s);}try(Connection c=dataSource.getConnection()){ensureSchema(c);try(PreparedStatement p=c.prepareStatement("UPDATE knowledge_sources SET status=?,updated_at=? WHERE source_id=?")){p.setString(1,status);p.setTimestamp(2,Timestamp.from(Instant.now()));p.setString(3,sourceId);p.executeUpdate();}insertEvent(c,sourceId,"SOURCE_"+status,actorId,s,Map.of("status",status));return getSource(sourceId,actorId);}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Source 状态未持久化",e);}}
    public Map<String,Object> setDocumentStatus(String documentId,String status,Long actorId){Map<String,Object>d=getDocument(documentId,actorId);Map<String,Object>s=source(String.valueOf(d.get("sourceId")));if(PACKAGED.equals(s.get("sourceType")))throw KnowledgeBackendException.forbidden(documentId);if(!ACTIVE.equals(status)&&!DISABLED.equals(status))throw KnowledgeBackendException.validation("status 只能是 ACTIVE 或 DISABLED");if(dataSource==null){d.put("status",status);d.put("updatedAt",Instant.now().toString());fallbackDocuments.put(documentId,d);fallbackEvent(d,"KNOWLEDGE_DOCUMENT_"+status,actorId);return copy(d);}try(Connection c=dataSource.getConnection()){ensureSchema(c);try(PreparedStatement p=c.prepareStatement("UPDATE knowledge_documents SET status=?,updated_at=? WHERE document_id=?")){p.setString(1,status);p.setTimestamp(2,Timestamp.from(Instant.now()));p.setString(3,documentId);p.executeUpdate();}insertEvent(c,documentId,"DOCUMENT_"+status,actorId,d,Map.of("status",status));return getDocument(documentId,actorId);}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Document 状态未持久化",e);}}

    /** Idempotently registers the existing curated classpath text as read-only packaged knowledge. */
    public Map<String,Object> ensurePackagedKnowledge(String originUri,String content){String normalized=normalize(content);String hash=sha256(normalized);if(dataSource==null){requireFallback();Map<String,Object>s=fallbackSources.values().stream().filter(x->PACKAGED.equals(x.get("sourceType"))&&originUri.equals(x.get("originUri"))).findFirst().orElse(null);if(s==null){s=new LinkedHashMap<>();s.put("sourceId",id("knowledge-source"));s.put("name","FarMap Curated Orchard Knowledge");s.put("sourceType",PACKAGED);s.put("originUri",originUri);s.put("ownerUserId",null);s.put("status",ACTIVE);now(s);fallbackSources.put((String)s.get("sourceId"),s);}String sid=String.valueOf(s.get("sourceId"));Map<String,Object>d=fallbackDocuments.values().stream().filter(x->sid.equals(x.get("sourceId"))&&originUri.equals(x.get("externalReference"))).findFirst().orElse(null);if(d==null){d=new LinkedHashMap<>();d.put("documentId",id("knowledge-document"));d.put("sourceId",sid);d.put("title","Orchard management");d.put("externalReference",originUri);d.put("ownerUserId",null);d.put("status",ACTIVE);d.put("currentVersionId",null);d.put("version",0L);now(d);fallbackDocuments.put((String)d.get("documentId"),d);}final String documentId=String.valueOf(d.get("documentId"));Map<String,Object>v=fallbackVersions.values().stream().filter(x->documentId.equals(x.get("documentId"))&&hash.equals(x.get("contentHash"))).findFirst().orElse(null);if(v==null){v=new LinkedHashMap<>();v.put("versionId",id("knowledge-version"));v.put("documentId",documentId);v.put("versionNumber",1);v.put("contentType","text/plain");v.put("content",normalized);v.put("contentHash",hash);v.put("createdBy",null);now(v);fallbackVersions.put((String)v.get("versionId"),v);}if(d.get("currentVersionId")==null){d.put("currentVersionId",v.get("versionId"));fallbackDocuments.put(documentId,d);}return copy(v);}try(Connection c=dataSource.getConnection()){ensureSchema(c);c.setAutoCommit(false);try{Map<String,Object>s=findPackagedSource(c,originUri);if(s==null){s=new LinkedHashMap<>();s.put("sourceId",id("knowledge-source"));s.put("name","FarMap Curated Orchard Knowledge");s.put("sourceType",PACKAGED);s.put("originUri",originUri);s.put("ownerUserId",null);s.put("status",ACTIVE);now(s);insertSource(c,s,null);}Map<String,Object>d=findPackagedDocument(c,(String)s.get("sourceId"),originUri);if(d==null){d=new LinkedHashMap<>();d.put("documentId",id("knowledge-document"));d.put("sourceId",s.get("sourceId"));d.put("title","Orchard management");d.put("externalReference",originUri);d.put("ownerUserId",null);d.put("status",ACTIVE);d.put("currentVersionId",null);d.put("version",0L);now(d);insertDocument(c,d);}Map<String,Object>v=findVersionByHash(c,String.valueOf(d.get("documentId")),hash);if(v==null){v=new LinkedHashMap<>();v.put("versionId",id("knowledge-version"));v.put("documentId",d.get("documentId"));v.put("versionNumber",nextVersion(c,String.valueOf(d.get("documentId"))));v.put("contentType","text/plain");v.put("content",normalized);v.put("contentHash",hash);v.put("createdBy",null);now(v);insertVersion(c,v);}if(d.get("currentVersionId")==null){try(PreparedStatement p=c.prepareStatement("UPDATE knowledge_documents SET current_version_id=?,version=version+1,updated_at=? WHERE document_id=?")){p.setString(1,String.valueOf(v.get("versionId")));p.setTimestamp(2,Timestamp.from(Instant.now()));p.setString(3,String.valueOf(d.get("documentId")));p.executeUpdate();}}c.commit();return v;}catch(Exception e){try{c.rollback();}catch(Exception ignored){}throw e;}finally{try{c.setAutoCommit(true);}catch(Exception ignored){}}}catch(Exception e){throw KnowledgeBackendException.persistence("Packaged Knowledge 注册不可用",e);}}

    public List<RetrievalUnit> retrieveCurrent(Long actorId){
        if(dataSource==null){requireFallback();return units(fallbackSources.values(),fallbackDocuments.values(),fallbackVersions.values(),actorId);}
        try(Connection c=dataSource.getConnection()){
            ensureSchema(c); List<RetrievalUnit> out=new ArrayList<>();
            String sql="SELECT s.source_id,s.name,s.owner_user_id,d.document_id,d.title,d.owner_user_id,d.current_version_id,v.version_id,v.content,v.content_hash FROM knowledge_sources s JOIN knowledge_documents d ON d.source_id=s.source_id JOIN knowledge_versions v ON v.version_id=d.current_version_id WHERE s.status='ACTIVE' AND d.status='ACTIVE' AND (s.owner_user_id IS NULL OR s.owner_user_id=? ) AND (d.owner_user_id IS NULL OR d.owner_user_id=?)";
            try(PreparedStatement p=c.prepareStatement(sql)){
                if(actorId==null){p.setNull(1,Types.BIGINT);p.setNull(2,Types.BIGINT);}else{p.setLong(1,actorId);p.setLong(2,actorId);}
                try(ResultSet r=p.executeQuery()){
                    while(r.next()){
                        List<RetrievalUnit> persisted;
                        try {
                            persisted = persistedChunks(c, r.getString(1), r.getString(2), r.getString(4), r.getString(5), r.getString(8));
                        } catch (SQLException ignored) {
                            // Older deployments may not have the chunk table yet;
                            // retain the version-level retrieval fallback there.
                            persisted = List.of();
                        }
                        if (persisted.isEmpty()) out.addAll(split(r.getString(1),r.getString(2),r.getString(4),r.getString(5),r.getString(8),r.getString(10),r.getString(9),null));
                        else out.addAll(persisted);
                    }
                }
            }
            return out;
        }catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Retrieval 不可用",e);}
    }
    public Map<String,Object> health(){if(dataSource==null)return Map.of("status",allowFallback?"DEMO":"UNAVAILABLE","mode",allowFallback?"fallback":"database");try(Connection c=dataSource.getConnection()){ensureSchema(c);long n=count(c,"knowledge_versions");return Map.of("status",n>0?"READY":"READY_EMPTY","mode","database","versions",n);}catch(Exception e){return Map.of("status","UNAVAILABLE","mode","database","error",e.getClass().getSimpleName());}}
    public static final class RetrievalUnit {
        public final String sourceId,sourceName,documentId,documentTitle,versionId,contentHash,chunkId,content,classification;
        RetrievalUnit(String a,String b,String c,String d,String e,String f,String g,String h){this(a,b,c,d,e,f,g,h,null);}
        RetrievalUnit(String a,String b,String c,String d,String e,String f,String g,String h,String i){sourceId=a;sourceName=b;documentId=c;documentTitle=d;versionId=e;contentHash=f;chunkId=g;content=h;classification=i;}
    }

    private List<RetrievalUnit> units(Collection<Map<String,Object>> sources,Collection<Map<String,Object>> documents,Collection<Map<String,Object>> versions,Long actor){Map<String,Map<String,Object>> ss=sources.stream().filter(s->ACTIVE.equals(s.get("status"))&&visible(s,actor)).collect(Collectors.toMap(s->String.valueOf(s.get("sourceId")),s->s));Map<String,Map<String,Object>> ds=documents.stream().filter(d->ACTIVE.equals(d.get("status"))&&ss.containsKey(String.valueOf(d.get("sourceId")))&&visible(d,actor)).collect(Collectors.toMap(d->String.valueOf(d.get("documentId")),d->d));List<RetrievalUnit>o=new ArrayList<>();for(Map<String,Object>v:versions){Map<String,Object>d=ds.get(String.valueOf(v.get("documentId")));if(d!=null&&String.valueOf(d.get("currentVersionId")).equals(String.valueOf(v.get("versionId"))))o.addAll(split(String.valueOf(d.get("sourceId")),String.valueOf(ss.get(String.valueOf(d.get("sourceId"))).get("name")),String.valueOf(d.get("documentId")),String.valueOf(d.get("title")),String.valueOf(v.get("versionId")),String.valueOf(v.get("contentHash")),String.valueOf(v.get("content")),null));}return o;}
    private List<RetrievalUnit> split(String sid,String sn,String did,String dn,String vid,String hash,String content,String classification){List<RetrievalUnit>o=new ArrayList<>();String[] ps=content.split("\\n\\s*\\n");int i=0;for(String p:ps){String x=p.replaceAll("\\s+"," ").trim();if(!x.isEmpty())o.add(new RetrievalUnit(sid,sn,did,dn,vid,hash,vid+"-chunk-"+(++i),x,classification));}return o;}
    private List<RetrievalUnit> persistedChunks(Connection c,String sourceId,String sourceName,String documentId,String documentTitle,String versionId) throws SQLException {
        List<RetrievalUnit> out = new ArrayList<>();
        try (PreparedStatement p = c.prepareStatement("SELECT chunk_id,content,content_hash,classification FROM knowledge_chunks WHERE version_id=? ORDER BY chunk_index")) {
            p.setString(1, versionId);
            try (ResultSet r = p.executeQuery()) {
                while (r.next()) out.add(new RetrievalUnit(sourceId, sourceName, documentId, documentTitle, versionId, r.getString(3), r.getString(1), r.getString(2), r.getString(4)));
            }
        }
        return out;
    }
    private Map<String,Object> source(String id){if(id==null||id.isBlank())throw KnowledgeBackendException.validation("sourceId 不能为空");if(dataSource==null){requireFallback();Map<String,Object>x=fallbackSources.get(id);if(x==null)throw KnowledgeBackendException.notFound("SOURCE_NOT_FOUND","Knowledge Source 不存在",id);return x;}try(Connection c=dataSource.getConnection()){ensureSchema(c);try(PreparedStatement p=c.prepareStatement("SELECT source_id,name,source_type,description,origin_uri,owner_user_id,status,created_at,updated_at FROM knowledge_sources WHERE source_id=?")){p.setString(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw KnowledgeBackendException.notFound("SOURCE_NOT_FOUND","Knowledge Source 不存在",id);return sourceRow(r);}}}catch(KnowledgeBackendException e){throw e;}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Source 查询不可用",e);}}
    private Map<String,Object> document(String id){if(dataSource==null){requireFallback();Map<String,Object>x=fallbackDocuments.get(id);if(x==null)throw KnowledgeBackendException.notFound("DOCUMENT_NOT_FOUND","Knowledge Document 不存在",id);return x;}try(Connection c=dataSource.getConnection()){ensureSchema(c);try(PreparedStatement p=c.prepareStatement("SELECT document_id,source_id,title,external_reference,owner_user_id,status,current_version_id,version,created_at,updated_at FROM knowledge_documents WHERE document_id=?")){p.setString(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw KnowledgeBackendException.notFound("DOCUMENT_NOT_FOUND","Knowledge Document 不存在",id);return documentRow(r);}}}catch(KnowledgeBackendException e){throw e;}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Document 查询不可用",e);}}
    private Map<String,Object> version(String id){if(dataSource==null){requireFallback();Map<String,Object>x=fallbackVersions.get(id);if(x==null)throw KnowledgeBackendException.notFound("VERSION_NOT_FOUND","Knowledge Version 不存在",id);return x;}try(Connection c=dataSource.getConnection()){ensureSchema(c);try(PreparedStatement p=c.prepareStatement("SELECT version_id,document_id,version_number,content_type,content,content_hash,created_by,created_at FROM knowledge_versions WHERE version_id=?")){p.setString(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw KnowledgeBackendException.notFound("VERSION_NOT_FOUND","Knowledge Version 不存在",id);return versionRow(r);}}}catch(KnowledgeBackendException e){throw e;}catch(Exception e){throw KnowledgeBackendException.persistence("Knowledge Version 查询不可用",e);}}
    private void authorize(Map<String,Object>x,Long actor){Object owner=x.get("ownerUserId");if(owner!=null&&(actor==null||!String.valueOf(owner).equals(String.valueOf(actor))))throw KnowledgeBackendException.forbidden(String.valueOf(x.getOrDefault("sourceId",x.getOrDefault("documentId",x.get("versionId")))));}
    private boolean visible(Map<String,Object>x,Long actor){Object owner=x.get("ownerUserId");return owner==null||(actor!=null&&String.valueOf(owner).equals(String.valueOf(actor)));}
    private boolean isDuplicate(SQLException error){for(SQLException current=error;current!=null;current=current.getNextException())if("23000".equals(current.getSQLState())||current.getErrorCode()==1062)return true;return false;}
    private void requireActor(Long actor){if(dataSource!=null&&actor==null)throw KnowledgeBackendException.forbidden(null);}
    private void requireFallback(){if(!allowFallback)throw KnowledgeBackendException.persistence("Knowledge 数据库不可用，已拒绝写入",null);}
    private String id(String prefix){return prefix+"-"+UUID.randomUUID();}
    private String required(Map<String,Object>m,String key){String x=optional(m,key);if(x==null)throw KnowledgeBackendException.validation(key+" 不能为空");return x;}
    private String optional(Map<String,Object>m,String key){Object x=m==null?null:m.get(key);return x==null||String.valueOf(x).isBlank()?null:String.valueOf(x).trim();}
    private String upper(Map<String,Object>m,String key,String fallback){String x=optional(m,key);return x==null?fallback:x.toUpperCase(Locale.ROOT);}
    private void now(Map<String,Object>x){String n=Instant.now().toString();x.put("createdAt",n);x.put("updatedAt",n);}
    private String normalize(String x){return x.replace("\r\n","\n").replace("\r","\n");}
    private String sha256(String x){try{byte[]b=MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8));StringBuilder o=new StringBuilder();for(byte z:b)o.append(String.format("%02x",z));return o.toString();}catch(Exception e){throw new IllegalStateException(e);}}
    private Map<String,Object> copy(Map<String,Object>x){return x==null?null:new LinkedHashMap<>(x);}
    private void event(Connection c,Map<String,Object>entity,String type,Long actor){if(dataSource!=null)try{insertEvent(c,String.valueOf(entity.getOrDefault("sourceId",entity.getOrDefault("documentId",entity.get("versionId")))),type,actor,null,entity);}catch(Exception ignored){}}
    private void fallbackEvent(Map<String,Object>entity,String type,Long actor){Map<String,Object>e=new LinkedHashMap<>();e.put("eventType",type);e.put("actorId",actor);e.put("entity",entity);e.put("createdAt",Instant.now().toString());fallbackEvents.put(id("knowledge-event"),e);}
    private void insertSource(Connection c,Map<String,Object>s,Long actor)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO knowledge_sources(source_id,name,source_type,description,origin_uri,owner_user_id,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)")){p.setString(1,String.valueOf(s.get("sourceId")));p.setString(2,String.valueOf(s.get("name")));p.setString(3,String.valueOf(s.get("sourceType")));set(p,4,s.get("description"));set(p,5,s.get("originUri"));setLong(p,6,(Long)s.get("ownerUserId"));p.setString(7,ACTIVE);p.setTimestamp(8,ts(s.get("createdAt")));p.setTimestamp(9,ts(s.get("updatedAt")));p.executeUpdate();}insertEvent(c,String.valueOf(s.get("sourceId")),"SOURCE_CREATED",actor,null,s);}
    private void insertDocument(Connection c,Map<String,Object>d)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO knowledge_documents(document_id,source_id,title,external_reference,owner_user_id,status,current_version_id,version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)")){p.setString(1,String.valueOf(d.get("documentId")));p.setString(2,String.valueOf(d.get("sourceId")));p.setString(3,String.valueOf(d.get("title")));set(p,4,d.get("externalReference"));setLong(p,5,(Long)d.get("ownerUserId"));p.setString(6,ACTIVE);set(p,7,d.get("currentVersionId"));p.setLong(8,0);p.setTimestamp(9,ts(d.get("createdAt")));p.setTimestamp(10,ts(d.get("updatedAt")));p.executeUpdate();}}
    private void insertVersion(Connection c,Map<String,Object>v)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO knowledge_versions(version_id,document_id,version_number,content_type,content,content_hash,created_by,created_at) VALUES(?,?,?,?,?,?,?,?)")){p.setString(1,String.valueOf(v.get("versionId")));p.setString(2,String.valueOf(v.get("documentId")));p.setInt(3,((Number)v.get("versionNumber")).intValue());p.setString(4,String.valueOf(v.get("contentType")));p.setString(5,String.valueOf(v.get("content")));p.setString(6,String.valueOf(v.get("contentHash")));setLong(p,7,(Long)v.get("createdBy"));p.setTimestamp(8,ts(v.get("createdAt")));p.executeUpdate();}}
    private Map<String,Object> sourceRow(ResultSet r)throws SQLException{Map<String,Object>x=new LinkedHashMap<>();x.put("sourceId",r.getString(1));x.put("name",r.getString(2));x.put("sourceType",r.getString(3));x.put("description",r.getString(4));x.put("originUri",r.getString(5));x.put("ownerUserId",r.getObject(6));x.put("status",r.getString(7));x.put("createdAt",instant(r.getTimestamp(8)));x.put("updatedAt",instant(r.getTimestamp(9)));return x;}
    private Map<String,Object> documentRow(ResultSet r)throws SQLException{Map<String,Object>x=new LinkedHashMap<>();x.put("documentId",r.getString(1));x.put("sourceId",r.getString(2));x.put("title",r.getString(3));x.put("externalReference",r.getString(4));x.put("ownerUserId",r.getObject(5));x.put("status",r.getString(6));x.put("currentVersionId",r.getString(7));x.put("version",r.getLong(8));x.put("createdAt",instant(r.getTimestamp(9)));x.put("updatedAt",instant(r.getTimestamp(10)));return x;}
    private Map<String,Object> versionRow(ResultSet r)throws SQLException{Map<String,Object>x=new LinkedHashMap<>();x.put("versionId",r.getString(1));x.put("documentId",r.getString(2));x.put("versionNumber",r.getInt(3));x.put("contentType",r.getString(4));x.put("content",r.getString(5));x.put("contentHash",r.getString(6));x.put("createdBy",r.getObject(7));x.put("createdAt",instant(r.getTimestamp(8)));return x;}
    private Timestamp ts(Object x){try{return x==null?null:Timestamp.from(x instanceof Instant?(Instant)x:Instant.parse(String.valueOf(x)));}catch(Exception e){return null;}}
    private String instant(Timestamp x){return x==null?null:x.toInstant().toString();}
    private void set(PreparedStatement p,int i,Object x)throws SQLException{if(x==null)p.setNull(i,Types.VARCHAR);else p.setString(i,String.valueOf(x));}
    private void setLong(PreparedStatement p,int i,Long x)throws SQLException{if(x==null)p.setNull(i,Types.BIGINT);else p.setLong(i,x);}
    private int nextVersion(Connection c,String did)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT COALESCE(MAX(version_number),0)+1 FROM knowledge_versions WHERE document_id=? FOR UPDATE")){p.setString(1,did);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}}
    private Map<String,Object> findVersionByHash(Connection c,String did,String hash)throws Exception{try(PreparedStatement p=c.prepareStatement("SELECT version_id,document_id,version_number,content_type,content,content_hash,created_by,created_at FROM knowledge_versions WHERE document_id=? AND content_hash=?")){p.setString(1,did);p.setString(2,hash);try(ResultSet r=p.executeQuery()){return r.next()?versionRow(r):null;}}}
    private Map<String,Object> findPackagedSource(Connection c,String uri)throws Exception{try(PreparedStatement p=c.prepareStatement("SELECT source_id,name,source_type,description,origin_uri,owner_user_id,status,created_at,updated_at FROM knowledge_sources WHERE source_type='PACKAGED' AND origin_uri=?")){p.setString(1,uri);try(ResultSet r=p.executeQuery()){return r.next()?sourceRow(r):null;}}}
    private Map<String,Object> findPackagedDocument(Connection c,String sid,String uri)throws Exception{try(PreparedStatement p=c.prepareStatement("SELECT document_id,source_id,title,external_reference,owner_user_id,status,current_version_id,version,created_at,updated_at FROM knowledge_documents WHERE source_id=? AND external_reference=?")){p.setString(1,sid);p.setString(2,uri);try(ResultSet r=p.executeQuery()){return r.next()?documentRow(r):null;}}}
    private void insertEvent(Connection c,String id,String type,Long actor,Map<String,Object>before,Map<String,Object>after)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO knowledge_events(event_id,entity_type,entity_id,event_type,actor_id,metadata_json,created_at) VALUES(?,?,?,?,?,?,?)")){p.setString(1,id("knowledge-event"));p.setString(2,"KNOWLEDGE");p.setString(3,id);p.setString(4,type);setLong(p,5,actor);set(p,6,json(Map.of("before",before==null?Map.of():before,"after",after==null?Map.of():after)));p.setTimestamp(7,Timestamp.from(Instant.now()));p.executeUpdate();}}
    private String json(Object x){try{return mapper.writeValueAsString(x);}catch(JsonProcessingException e){return "{}";}}
    private long count(Connection c,String table)throws SQLException{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM "+table)){r.next();return r.getLong(1);}}
     public void ensureSchema(Connection c)throws SQLException{if(schemaChecked)return;synchronized(this){if(schemaChecked)return;try(Statement s=c.createStatement()){s.execute("CREATE TABLE IF NOT EXISTS knowledge_sources (source_id VARCHAR(112) NOT NULL,name VARCHAR(255) NOT NULL,source_type VARCHAR(32) NOT NULL,description TEXT NULL,origin_uri VARCHAR(255) NULL,owner_user_id BIGINT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP(3) NOT NULL,updated_at TIMESTAMP(3) NOT NULL,PRIMARY KEY(source_id),UNIQUE KEY uk_knowledge_source_origin(source_type,origin_uri),INDEX idx_knowledge_source_owner(owner_user_id),INDEX idx_knowledge_source_status(status)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");s.execute("CREATE TABLE IF NOT EXISTS knowledge_documents (document_id VARCHAR(112) NOT NULL,source_id VARCHAR(112) NOT NULL,title VARCHAR(255) NOT NULL,external_reference VARCHAR(512) NULL,owner_user_id BIGINT NULL,status VARCHAR(32) NOT NULL,current_version_id VARCHAR(112) NULL,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP(3) NOT NULL,updated_at TIMESTAMP(3) NOT NULL,PRIMARY KEY(document_id),INDEX idx_knowledge_document_source(source_id),INDEX idx_knowledge_document_owner(owner_user_id),INDEX idx_knowledge_document_current(current_version_id)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");s.execute("CREATE TABLE IF NOT EXISTS knowledge_versions (version_id VARCHAR(112) NOT NULL,document_id VARCHAR(112) NOT NULL,version_number INT NOT NULL,content_type VARCHAR(128) NOT NULL,content LONGTEXT NOT NULL,content_hash CHAR(64) NOT NULL,created_by BIGINT NULL,created_at TIMESTAMP(3) NOT NULL,PRIMARY KEY(version_id),UNIQUE KEY uk_knowledge_version_hash(document_id,content_hash),UNIQUE KEY uk_knowledge_version_number(document_id,version_number),INDEX idx_knowledge_version_document(document_id)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");s.execute("CREATE TABLE IF NOT EXISTS knowledge_events (event_id VARCHAR(112) NOT NULL,entity_type VARCHAR(64) NOT NULL,entity_id VARCHAR(112) NOT NULL,event_type VARCHAR(64) NOT NULL,actor_id BIGINT NULL,metadata_json LONGTEXT NULL,created_at TIMESTAMP(3) NOT NULL,PRIMARY KEY(event_id),INDEX idx_knowledge_event_entity(entity_id),INDEX idx_knowledge_event_created(created_at)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");s.execute("ALTER TABLE knowledge_sources CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");s.execute("ALTER TABLE knowledge_documents CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");s.execute("ALTER TABLE knowledge_versions CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");s.execute("ALTER TABLE knowledge_events CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");schemaChecked=true;}}}
}
